catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading || newValue !== 'subscribe') {
        return;
    }

    var choice = 'outage_shield_choice';
    var offering = g_form.getValue(
        'affected_service_offering'
    );

    g_form.hideFieldMsg(choice, true);

    if (!offering) {
        g_form.showFieldMsg(
            choice,
            'Please select a Service Offering.',
            'error',
            false
        );
        return;
    }

    g_form.showFieldMsg(
        choice,
        'Processing your subscription...',
        'info',
        false
    );

    var ga = new GlideAjax(
        'x_1951923_outage_0.OutageShieldAdvisoryAjax'
    );

    ga.addParam(
        'sysparm_name',
        'subscribeCurrentUser'
    );

    ga.addParam(
        'sysparm_service_key',
        offering
    );

    ga.getXMLAnswer(function(answer) {

        if (g_form.getValue(
            'affected_service_offering'
        ) !== offering) {
            return;
        }

        var result;

        try {
            result = JSON.parse(answer || '{}');
        } catch (e) {
            result = {
                success: false,
                message: 'Subscription request failed.'
            };
        }

        if (g_form.getValue(choice) !== 'subscribe') {
            return;
        }

        g_form.hideFieldMsg(choice, true);

        if (result.success) {

            g_form.showFieldMsg(
                choice,
                result.message +
                ' No Incident has been created. ' +
                'You can close this form. ' +
                'Outage Shield email notifications ' +
                'are not active yet.',
                'info',
                false
            );

        } else {

            g_form.showFieldMsg(
                choice,
                result.message ||
                    'Unable to complete subscription.',
                'error',
                false
            );
        }
    });
}
